n.exploreUrl:
@js:
sort = [];
push = (title, url, type) => sort.push({
    title: title,
    url: url,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: type
    }
});

url = (theme) => `@js:
"https://api.mangacopy.com/api/v3/books?ordering=-datetime_updated&limit=21&offset={{(page-1)*21}}&free_type=1&theme=${theme}&_update=true"` 

push("全部题材", "", 1)
tagUrl = 'https://api.mangacopy.com/api/v3/theme/book/count?free_type=1&limit=500&offset=0&_update=true' 
let $ = JSON.parse(java.ajax(tagUrl)).results.list
$.forEach(($) => {
  push($.name, url($.path_word), 0.25)
})

JSON.stringify(sort)

ruleContent.content:
@js:
var url = java.getString('$..txt_addr')
var text = java.cacheFile(url)
var img = java.getString('$..content')
var ims = img.match(/https?:\/\/.+\.(jpg|jpeg|webp)/gi); 
if (ims) {
    imgs = ims.map(x => `<img src="${x}">`).join('\n');
    }
text + imgs
